from pathlib import Path
import base64,hashlib,json,os,subprocess,difflib
R=Path('/srv/android/asus-minimal-platform-preparation-20261108');K=R/'kernel';O=R/'out';B=Path('/srv/android/asus-linux49-calibrated-entry-build-20261107')
assert not (R/'evidence/config-resolution.json').exists(), 'one resolution only'
payload={'out/.config': '', 'kernel/init/main.c': '', 'kernel/arch/arm64/boot/dts/mediatek/asus-p00a.dts': ''}
for n,v in payload.items():
 p=R/n
 if n.startswith('kernel/'):
  assert p.read_bytes()==(B/n).read_bytes()
 p.write_bytes(base64.b64decode(v))
conf=B/'out/scripts/kconfig/conf'
env=dict(os.environ,ARCH='arm64',SRCARCH='arm64',KERNELVERSION='4.9.337',srctree=str(K),objtree=str(O),KCONFIG_CONFIG=str(O/'.config'),CC='aarch64-linux-gnu-gcc',HOSTCC='gcc')
q=subprocess.run([str(conf),'--olddefconfig','Kconfig'],cwd=K,env=env,text=True,capture_output=True)
assert q.returncode==0,q.stderr
files={}
paths={'config/resolved.config':O/'.config'}
for n in ['drivers/misc/mediatek/include/mt-plat/battery_common.h','drivers/misc/mediatek/include/mt-plat/mt8163/include/mach/mtk_charging.h']:
 if (K/n).is_file():paths['source/baseline/'+n]=K/n
for name,p in paths.items():
 b=p.read_bytes();files[name]=dict(data=base64.b64encode(b).decode(),sha256=hashlib.sha256(b).hexdigest())
receipt=dict(command=[str(conf),'--olddefconfig','Kconfig'],environment={k:env[k] for k in ['ARCH','SRCARCH','KERNELVERSION','srctree','objtree','KCONFIG_CONFIG','CC','HOSTCC']},stdout=q.stdout,stderr=q.stderr,exit=q.returncode,compiled_kernel=False,compiled_helper=False,compiled_host_tools=False,resolved_config_sha256=files['config/resolved.config']['sha256'])
(R/'evidence/config-resolution.json').write_text(json.dumps(receipt,indent=2)+'\n')
print(json.dumps(dict(files=files,**receipt)))
